        goto fill_fault_output;
    }

    size_t count = qo_input.count;
    if (count != 2 && count != 3) {
        qo_state.mode = QO_FAULT;
        goto fill_fault_output;
    }

    if (!isfinite(qo_config.minimum_weight) || qo_config.minimum_weight <= 0.0 ||
        !isfinite(qo_config.minimum_separation_sine) || 
        qo_config.minimum_separation_sine <= 0.0 || qo_config.minimum_separation_sine > 1.0 ||
        !isfinite((float64)qo_config.required_good) || 
        qo_config.required_good < 1 || qo_config.required_good > 10 ||
        !isfinite((float64)qo_config.max_consecutive_bad) || 
        qo_config.max_consecutive_bad > 10) {
        qo_state.mode = QO_FAULT;
        goto fill_fault_output;
    }

    // 2. Handle Disable
    if (!qo_input.enable) {
        qo_state.mode = QO_WAIT;
        qo_state.good = 0;
        qo_state.bad_streak = 0;
        goto fill_normal_output;
    }

    // 3. Validate Data and Compute Weighted Body
    double total_weight = 0.0;
    adcs_vec3_t weighted_body_sum = {0, 0, 0};
    adcs_vec3_t norm_body[3];
    adcs_vec3_t norm_ref[3];
    int data_valid = 1;

    for (size_t i = 0; i < count; ++i) {
        if (!isfinite(qo_input.weights[i]) || qo_input.weights[i] <= 0.0) {
            data_valid = 0;
            break;
        }

        if (adcs_vec3_normalize(&qo_input.body[i], ADCS_EPS_NORM, &norm_body[i]) != ADCS_OK) {
            data_valid = 0;
            break;
        }
        if (adcs_vec3_normalize(&qo_input.reference[i], ADCS_EPS_NORM, &norm_ref[i]) != ADCS_OK) {
            data_valid = 0;
            break;
        }

        total_weight += qo_input.weights[i];
        adcs_vec3_t term = adcs_vec3_scale(&norm_body[i], qo_input.weights[i]);
        weighted_body_sum = adcs_vec3_add(&weighted_body_sum, &term);
    }

    if (!data_valid) {
        qo_state.mode = QO_FAULT;
        goto fill_fault_output;
    }

    // 4. Compute Separation Sines using first two vectors
    adcs_vec3_t cross_b = adcs_vec3_cross(&norm_body[0], &norm_body[1]);
    adcs_vec3_t cross_r = adcs_vec3_cross(&norm_ref[0], &norm_ref[1]);

    double body_sep_sine = adcs_vec3_norm(&cross_b);
    double ref_sep_sine = adcs_vec3_norm(&cross_r);

    // 5. Determine Usability
    unint32 usable = 0;
    if (total_weight >= qo_config.minimum_weight &&
        body_sep_sine >= qo_config.minimum_separation_sine &&
        ref_sep_sine >= qo_config.minimum_separation_sine) {
        usable = 1;
    }

    // 6. State Machine Transition
    if (usable == 1) {
        qo_state.good++;
        qo_state.bad_streak = 0;
        if (qo_state.good >= qo_config.required_good) {
            qo_state.mode = QO_SOLVE;
        } else {
            qo_state.mode = QO_WAIT;
        }
    } else {
        qo_state.bad_streak++;
        if (qo_state.bad_streak > qo_config.max_consecutive_bad) {
            qo_state.mode = QO_WAIT;
            qo_state.good = 0;
            qo_state.bad_streak = 0;
        } else {
            qo_state.mode = QO_HOLD;
        }
    }

